"""Coverage for src/scripts/lib/footnote_backrefs.py -- the local-to-global
footnote self-reference remapper.

Bug being fixed: each writer unit (one entry in data["sections"], the
article-assembly JSON fed to src/scripts/generate-docx.py) is drafted
independently and numbers its own footnotes starting from 1 in its own
prose. A self-reference like "שוורץ (לעיל, הערה 6), עמ' 323" uses that
unit's own LOCAL footnote ordinal, but the reader-visible footnote number
in the final DOCX is the GLOBAL ordinal FootnoteAdder.add_footnote()
(src/scripts/lib/footnote_adder.py) assigns while walking every section in
document order. Nothing previously rewrote the literal "הערה N" text to
match, producing broken cross-references.

Hard correctness constraint under test: only "לעיל, הערה N" (comma/
whitespace tolerant) is a genuine intra-article self-reference and gets
remapped. A bare "הערה N" NOT preceded by "לעיל" (e.g. "עמ' 243, הערה 59",
a CITED WORK's own footnote apparatus) must be left byte-for-byte
unchanged.
"""

from __future__ import annotations

import os
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LIB_DIR = os.path.join(ROOT_DIR, "src", "scripts", "lib")
SCRIPTS_DIR = os.path.join(ROOT_DIR, "src", "scripts")
if LIB_DIR not in sys.path:
    sys.path.insert(0, LIB_DIR)
if SCRIPTS_DIR not in sys.path:
    sys.path.insert(0, SCRIPTS_DIR)

from footnote_backrefs import remap_backreferences, warn_unresolved  # noqa: E402


def make_footnote(text, after="x"):
    return {"after": after, "text": text}


class LocalToGlobalRemapTests(unittest.TestCase):
    def test_second_section_backref_uses_global_not_local_ordinal(self):
        # Section 1: 3 footnotes (no self-references).
        section1 = {
            "title": "חלק א",
            "paragraphs": [
                {
                    "text": "פסקה עם שלוש הערות א ב ג",
                    "footnotes": [
                        make_footnote("שוורץ, מאמר א (2020), עמ' 10.", after="א"),
                        make_footnote("שוורץ, מאמר ב (2021), עמ' 20.", after="ב"),
                        make_footnote("שוורץ, מאמר ג (2022), עמ' 30.", after="ג"),
                    ],
                }
            ],
        }
        # Section 2: its own local footnote #2 is self-referenced from
        # local footnote #2's own body text (referring to itself is odd
        # but exercises the exact off-by-N mechanics) -- more realistically
        # this would be a later footnote referencing an earlier one, so
        # also add a 3rd footnote in section 2 that references local #2.
        section2 = {
            "title": "חלק ב",
            "paragraphs": [
                {
                    "text": "פסקה בחלק השני עם שתי הערות ראשונות",
                    "footnotes": [
                        make_footnote("דוניץ, מאמר (2019), עמ' 5.", after="ר"),
                        make_footnote("שוורץ, מאמר ב (2021), עמ' 21.", after="ש"),
                    ],
                },
                {
                    "text": "פסקה שלישית בחלק השני",
                    "footnotes": [
                        make_footnote(
                            "ראו שוורץ (לעיל, הערה 2), עמ' 323.", after="ר"
                        ),
                    ],
                },
            ],
        }
        sections = [section1, section2]

        rewritten, unresolved = remap_backreferences(sections)

        self.assertEqual(unresolved, [])

        # section 1 has 3 footnotes -> section 2's local footnote #2 is
        # global footnote #(3 + 2) = 5.
        rewritten_text = rewritten[1]["paragraphs"][1]["footnotes"][0]["text"]
        self.assertIn("הערה 5", rewritten_text)
        self.assertNotIn("הערה 2", rewritten_text)
        self.assertEqual(
            rewritten_text, "ראו שוורץ (לעיל, הערה 5), עמ' 323."
        )

    def test_input_sections_not_mutated(self):
        section1 = {
            "paragraphs": [
                {
                    "text": "פסקה",
                    "footnotes": [make_footnote("א", after="פ"), make_footnote("ב", after="ה")],
                }
            ]
        }
        section2 = {
            "paragraphs": [
                {
                    "text": "פסקה שנייה",
                    "footnotes": [
                        make_footnote("ראו לעיל, הערה 1.", after="פ"),
                    ],
                }
            ]
        }
        sections = [section1, section2]
        original_text = sections[1]["paragraphs"][0]["footnotes"][0]["text"]

        remap_backreferences(sections)

        # The original input list must be untouched -- generate_docx()
        # reassigns its local `sections` name to the returned value rather
        # than relying on in-place mutation, so the caller's own copy of
        # `data["sections"]` (if kept around) must not silently change too.
        self.assertEqual(
            sections[1]["paragraphs"][0]["footnotes"][0]["text"], original_text
        )


class BothPatternsInSameStringTests(unittest.TestCase):
    def test_leil_hearah_remapped_and_citations_own_note_number_untouched(self):
        # Section 1 has 5 footnotes so that section 2's local #3 becomes
        # global #8.
        section1 = {
            "paragraphs": [
                {
                    "text": "פסקה עם חמש הערות",
                    "footnotes": [make_footnote(f"מקור {i}", after=str(i)) for i in range(5)],
                }
            ]
        }
        mixed_text = (
            "שוורץ (לעיל, הערה 3) התייחס לסוגיה זו, בעוד שדוניץ "
            "כתב על כך בספרו בעמ' 243, הערה 59, ללא קשר לענייננו."
        )
        section2 = {
            "paragraphs": [
                {
                    "text": mixed_text,
                    "footnotes": [
                        make_footnote("x", after="0"),
                        make_footnote("x", after="1"),
                        make_footnote("x", after="2"),
                    ],
                }
            ]
        }
        sections = [section1, section2]

        rewritten, unresolved = remap_backreferences(sections)
        self.assertEqual(unresolved, [])

        out_text = rewritten[1]["paragraphs"][0]["text"]

        # The genuine self-reference IS remapped: local 3 -> global 5+3=8.
        self.assertIn("לעיל, הערה 8", out_text)
        self.assertNotIn("לעיל, הערה 3", out_text)

        # The cited work's OWN footnote number is left byte-for-byte
        # unchanged -- "עמ' 243, הערה 59" must survive verbatim, and must
        # NOT have been reinterpreted as a self-reference.
        self.assertIn("עמ' 243, הערה 59", out_text)

        expected = (
            "שוורץ (לעיל, הערה 8) התייחס לסוגיה זו, בעוד שדוניץ "
            "כתב על כך בספרו בעמ' 243, הערה 59, ללא קשר לענייננו."
        )
        self.assertEqual(out_text, expected)


class UnresolvedReferenceTests(unittest.TestCase):
    def test_backref_with_no_matching_local_footnote_left_unchanged_and_reported(self):
        section1 = {
            "paragraphs": [
                {
                    "text": "פסקה עם הערה אחת בלבד המפנה לעצמה: לעיל, הערה 6.",
                    "footnotes": [make_footnote("x", after="א")],
                }
            ]
        }
        sections = [section1]
        original_text = section1["paragraphs"][0]["text"]

        rewritten, unresolved = remap_backreferences(sections)

        # Text is left unchanged -- local note 6 does not exist (this
        # section only has 1 footnote).
        self.assertEqual(rewritten[0]["paragraphs"][0]["text"], original_text)
        self.assertIn("לעיל, הערה 6", rewritten[0]["paragraphs"][0]["text"])

        # Not silently dropped -- shows up in the unresolved list.
        self.assertEqual(len(unresolved), 1)
        self.assertEqual(unresolved[0]["section_index"], 0)
        self.assertEqual(unresolved[0]["local_ordinal"], 6)

    def test_warn_unresolved_writes_to_stderr_non_fatal(self):
        import io

        unresolved = [
            {"section_index": 0, "local_ordinal": 6, "context": "לעיל, הערה 6"}
        ]
        buf = io.StringIO()
        warn_unresolved(unresolved, stream=buf)
        output = buf.getvalue()
        self.assertIn("6", output)
        self.assertIn("section 0", output)

    def test_warn_unresolved_no_op_on_empty_list(self):
        import io

        buf = io.StringIO()
        warn_unresolved([], stream=buf)
        self.assertEqual(buf.getvalue(), "")


class GenerateDocxIntegrationTests(unittest.TestCase):
    """Thin integration test confirming generate-docx.py actually calls
    remap_backreferences() and that the GLOBAL (not local) ordinal ends up
    in the rendered footnote text inside the real .docx footnotes part."""

    def setUp(self):
        import importlib.util

        script_path = os.path.join(SCRIPTS_DIR, "generate-docx.py")
        spec = importlib.util.spec_from_file_location("generate_docx_module", script_path)
        self.module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(self.module)

        self._tmpdir_ctx = tempfile.TemporaryDirectory()
        self.tmpdir = self._tmpdir_ctx.name

    def tearDown(self):
        self._tmpdir_ctx.cleanup()

    def test_docx_footnote_text_carries_global_ordinal(self):
        import zipfile

        from lxml import etree

        data = {
            "title": "מאמר בדיקה",
            "thesis": None,
            "sections": [
                {
                    "title": "חלק א",
                    "paragraphs": [
                        {
                            "text": "פסקה ראשונה עם הערה",
                            "footnotes": [make_footnote("שוורץ, מאמר (2020).", after="ראשונה")],
                        }
                    ],
                },
                {
                    "title": "חלק ב",
                    "paragraphs": [
                        {
                            "text": "פסקה שנייה עם הפניה עצמית",
                            "footnotes": [
                                make_footnote(
                                    "ראו לעיל, הערה 1, ולא הערה אחרת.", after="שנייה"
                                )
                            ],
                        }
                    ],
                },
            ],
            "format": {"isRtl": True},
            "totalWords": 10,
        }
        output_path = os.path.join(self.tmpdir, "test-article.docx")

        self.module.generate_docx(data, output_path)

        self.assertTrue(os.path.exists(output_path))

        with zipfile.ZipFile(output_path, "r") as zf:
            footnotes_xml = zf.read("word/footnotes.xml")
        root = etree.fromstring(footnotes_xml)
        w_ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
        all_text = "".join(t.text or "" for t in root.iter("{%s}t" % w_ns))

        # Section 1 has 1 footnote, so section 2's local footnote #1 is
        # global footnote #2 -- the rendered footnote text must say
        # "הערה 2", never the unresolved local "הערה 1".
        self.assertIn("לעיל, הערה 2", all_text)
        self.assertNotIn("לעיל, הערה 1", all_text)


if __name__ == "__main__":
    unittest.main()
